using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
using PeopleHub.Domain.Security;
namespace PeopleHub.Tests;
public class PrivacySecurityTests
{
 class User(params string[] grants):ICurrentUser{public string Email=>"privacy@example.local";public int? EmployeeId{get;init;}=1;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>grants.Contains(p);}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static PerfService Perf(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,u,new AccessScope(d,u),c,a,new NotificationService(d,u,c));}
 static async Task<int> Setup(AppDbContext d,int? minimum=2){var c=new PerfCycle{Name="Privacy test",Start=new(2026,1,1),End=new(2026,12,31),MinimumFeedbackReviewers=minimum,GoalWeight=0,ManagerWeight=0,FeedbackWeight=100};d.Add(c);await d.SaveAsync();var a=new PerfAppraisal{CycleId=c.Id,EmployeeId=6,ManagerDone=true};d.Add(a);await d.SaveAsync();d.Add(new Feedback360{AppraisalId=a.Id,ReviewerEmployeeId=7,Score=4,Comment="Private comment",SubmittedAt=DateTime.UtcNow});await d.SaveAsync();return a.Id;}
 [Fact]public async Task TalentPermissionDoesNotGrantRawOrAggregateFeedback(){await using var d=await Db();int id=await Setup(d);var t=await Perf(d,new(Perm.TalentManage)).ToolsAsync(id);Assert.Empty(t.Feedback);Assert.Null(t.FeedbackAverage);}
 [Fact]public async Task IdentityGrantDoesNotExposeCommentsOrScores(){await using var d=await Db();int id=await Setup(d);var t=await Perf(d,new(Perm.TalentManage,Perm.FeedbackIdentity)).ToolsAsync(id);Assert.NotNull(t.Feedback.Single().ReviewerName);Assert.Null(t.Feedback.Single().Comment);Assert.Null(t.Feedback.Single().Score);}
 [Fact]public async Task CommentGrantDoesNotReturnReviewerIdentity(){await using var d=await Db();int id=await Setup(d);var t=await Perf(d,new(Perm.TalentManage,Perm.FeedbackComments)).ToolsAsync(id);Assert.Null(t.Feedback.Single().ReviewerName);Assert.Equal("Private comment",t.Feedback.Single().Comment);Assert.Equal(4,t.Feedback.Single().Score);}
 [Fact]public async Task ThresholdGatesBothPublishedAggregateAndWeightedScore(){await using var d=await Db();int id=await Setup(d);var s=Perf(d,new(Perm.TalentManage,Perm.FeedbackAggregate));Assert.Null((await s.ToolsAsync(id)).FeedbackAverage);Assert.Null((await s.GetAsync(id)).Computed);d.Add(new Feedback360{AppraisalId=id,ReviewerEmployeeId=8,Score=2,SubmittedAt=DateTime.UtcNow});await d.SaveAsync();Assert.Equal(3m,(await s.ToolsAsync(id)).FeedbackAverage);Assert.Equal(3m,(await s.GetAsync(id)).Computed);}
 [Fact]public async Task UnsetThresholdDoesNotPublishOrCalculateFeedback(){await using var d=await Db();int id=await Setup(d,null);var s=Perf(d,new(Perm.TalentManage,Perm.FeedbackAggregate));Assert.Null((await s.ToolsAsync(id)).FeedbackAverage);Assert.Null((await s.GetAsync(id)).Computed);}
 [Fact]public async Task SubmittedFeedbackFreezesThreshold(){await using var d=await Db();int id=await Setup(d);var a=await d.Set<PerfAppraisal>().FindAsync(id);await Assert.ThrowsAsync<DomainException>(()=>Perf(d,new(Perm.AdmRoles)).ConfigureFeedbackPrivacyAsync(a!.CycleId,3));Assert.Equal(2,(await d.Set<PerfCycle>().FindAsync(a!.CycleId))!.MinimumFeedbackReviewers);}
 [Fact]public async Task FiveFailuresLockAccountAndAuditWithoutPassword(){await using var d=await Db();var c=new AppClock(TimeProvider.System);var s=new AuthService(d,c);for(int i=0;i<5;i++)Assert.Null(await s.LoginAsync("hr@peoplehub.local","wrong"));var u=await d.Set<AppUser>().SingleAsync(x=>x.Email=="hr@peoplehub.local");Assert.True(u.LockedUntil>c.UtcNow);Assert.Null(await s.LoginAsync(u.Email,"Admin123!"));Assert.Single(await d.Set<AuditLog>().Where(x=>x.Action=="AccountLocked").ToListAsync());u.LockedUntil=c.UtcNow.AddSeconds(-1);await d.SaveAsync();Assert.NotNull(await s.LoginAsync(u.Email,"Admin123!"));Assert.Null(u.LockedUntil);Assert.Equal(0,u.FailedLoginCount);}
 [Fact]public async Task SuccessfulLoginResetsFailures(){await using var d=await Db();var s=new AuthService(d,new AppClock(TimeProvider.System));Assert.Null(await s.LoginAsync("hr@peoplehub.local","wrong"));Assert.NotNull(await s.LoginAsync("hr@peoplehub.local","Admin123!"));Assert.Equal(0,(await d.Set<AppUser>().SingleAsync(x=>x.Email=="hr@peoplehub.local")).FailedLoginCount);}
 [Fact]public async Task NoEmployeeLinkCannotBecomeManagerOfUnmanagedEmployee(){await using var d=await Db();int id=await Setup(d);var a=(await d.Set<PerfAppraisal>().FindAsync(id))!;var e=(await d.Set<Employee>().FindAsync(a.EmployeeId))!;e.ManagerId=null;await d.SaveAsync();var u=new User(Perm.ScopeCompany){EmployeeId=null};await Assert.ThrowsAsync<DomainException>(()=>Perf(d,u).GetAsync(id));Assert.Empty(await Perf(d,u).ListAsync(a.CycleId));await Assert.ThrowsAsync<DomainException>(()=>Perf(d,u).AddDevAsync(id,"Unauthorized",null));}

 [Fact]public async Task SelfToolsDoNotReturnReviewerDirectory(){await using var d=await Db();int id=await Setup(d);var t=await Perf(d,new User(){EmployeeId=6}).ToolsAsync(id);Assert.Empty(t.Employees);}
 [Fact]public async Task ManagerToolsReturnOnlyMinimalReviewerOptions(){await using var d=await Db();int id=await Setup(d);var t=await Perf(d,new(Perm.TalentManage)).ToolsAsync(id);Assert.NotEmpty(t.Employees);Assert.DoesNotContain(t.Employees,x=>x.Id==6);Assert.Equal(new[]{"FullName","FullNameAr","Id"},typeof(ReviewerOption).GetProperties().Select(x=>x.Name).OrderBy(x=>x).ToArray());}
}
